def ml_bias_variance_decomposition(P=None, f=None):
    """Bias-variance decomposition of predictions. For predictions of several models (one row each, e.g. trained on different samples) at the same test points with known noise-free values: the squared bias, the variance and the expected squared error, which equals their sum.
    Formula: E[(\\hat f - f)^2] = (E[\\hat f] - f)^2 + E[(\\hat f - E[\\hat f])^2]
    Inputs:
        P: predictions: one row per trained model, one column per test point (at least two rows)
        f: true (noise-free) value at each test point
    Outputs: bias_squared (mean over points of (mean prediction - f)^2), variance (mean over points of the variance of the predictions (divide by the number of models)), expected_mse (mean squared error over models and points = bias^2 + variance)
    See also: help("ml_bias_variance_decomposition")
    """
    given = {k: v for k, v in dict(P=P, f=f).items() if v is not None}
    return _P.solve("ml_bias_variance_decomposition", **given)

